package android.util;import java.util.*;public class SparseIntArray{Map<Integer,Integer>a=new TreeMap<>();public SparseIntArray(int n){}public int get(int k,int d){return a.getOrDefault(k,d);}public void put(int k,int v){a.put(k,v);}public int indexOfValue(int v){int i=0;for(int n:a.values()){if(n==v)return i;i++;}return -1;}public void clear(){a.clear();}public int size(){return a.size();}}
